import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/var/app/uploads')
MAX_FILE_SIZE = int(os.environ.get('MAX_FILE_SIZE', 10485760))
ALLOWED_EXTENSIONS = {'yaml', 'yml', 'json', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_config(config_data):
    """Validate configuration structure before processing"""
    required_keys = ['version', 'pipeline']
    if not isinstance(config_data, dict):
        return False, "Config must be a mapping"
    for key in required_keys:
        if key not in config_data:
            return False, f"Missing required key: {key}"
    if not isinstance(config_data.get('pipeline'), list):
        return False, "pipeline must be a sequence"
    return True, None

def execute_pipeline_step(step):
    """Execute a single pipeline step from config"""
    step_type = step.get('type', 'echo')
    if step_type == 'transform':
        input_file = step.get('input', '')
        output_file = step.get('output', '')
        transform_cmd = step.get('command', 'cat')
        # Build transformation command
        cmd = f"{transform_cmd} {input_file} > {output_file}"
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30, text=True)
        return {'status': 'completed', 'stdout': result.stdout[:500], 'returncode': result.returncode}
    elif step_type == 'validate':
        schema = step.get('schema', '')
        target = step.get('target', '')
        result = subprocess.run(['python3', '-c', f"import json; json.load(open('{target}'))"],
                              capture_output=True, timeout=10, text=True)
        return {'status': 'completed', 'valid': result.returncode == 0}
    elif step_type == 'notify':
        return {'status': 'completed', 'message': step.get('message', 'done')}
    else:
        return {'status': 'skipped', 'reason': f'unknown type: {step_type}'}

@app.route('/api/v2/pipeline/upload', methods=['POST'])
def upload_config():
    """Upload a pipeline configuration file"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    content = file.read()
    if len(content) > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    filename = secure_filename(file.filename)
    filepath = os.path.join(UPLOAD_DIR, filename)

    with open(filepath, 'wb') as f:
        f.write(content)

    return jsonify({'status': 'uploaded', 'filename': filename, 'path': filepath}), 201

@app.route('/api/v2/pipeline/execute', methods=['POST'])
def execute_pipeline():
    """Execute a previously uploaded pipeline configuration"""
    data = request.get_json()
    if not data or 'filename' not in data:
        return jsonify({'error': 'filename required'}), 400

    filename = secure_filename(data['filename'])
    filepath = os.path.join(UPLOAD_DIR, filename)

    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    with open(filepath, 'r') as f:
        # Parse YAML configuration
        config = yaml.safe_load(f)

    valid, err = validate_config(config)
    if not valid:
        return jsonify({'error': f'Invalid config: {err}'}), 400

    results = []
    for i, step in enumerate(config['pipeline']):
        try:
            result = execute_pipeline_step(step)
            results.append({'step': i, **result})
        except subprocess.TimeoutExpired:
            results.append({'step': i, 'status': 'timeout'})
        except Exception as e:
            results.append({'step': i, 'status': 'error', 'detail': str(e)})

    return jsonify({'pipeline': data['filename'], 'results': results})

@app.route('/api/v2/pipeline/status', methods=['GET'])
def pipeline_status():
    """List uploaded pipeline configs"""
    files = os.listdir(UPLOAD_DIR)
    return jsonify({'configs': files, 'upload_dir': UPLOAD_DIR})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.4'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
